    'The minimum number of approvals required in total or per reviewer group.' => 'Ο ελάχιστος αριθμός εγκρίσεων που απαιτείται συνολικά ή ανά ομάδα αξιολογητών.',
    'The navigation everyone gets. User group navigations build on it.' => 'Η πλοήγηση που λαμβάνουν όλοι. Οι πλοηγήσεις ομάδων χρηστών βασίζονται σε αυτήν.',
