    'The release no longer exists.' => 'Η κυκλοφορία δεν υπάρχει πλέον.',
    'The release “{name}” could not be published. {error}' => 'Δεν ήταν δυνατή η δημοσίευση της κυκλοφορίας «{name}». {error}',
    'The reserved [craft] asset transformer must use the [craft] driver.' => 'Ο δεσμευμένος μετασχηματιστής αρχείων [craft] πρέπει να χρησιμοποιεί το πρόγραμμα οδήγησης [craft].',
    'The review for “{entry}” was reset because its workflow changed.' => 'Η αξιολόγηση για το «{entry}» επαναφέρθηκε επειδή άλλαξε η ροή εργασιών της.',
    'The route is invalid.' => 'Η διαδρομή δεν είναι έγκυρη.',
