    'The selected asset transform driver has invalid settings.' => 'Το επιλεγμένο πρόγραμμα οδήγησης μετασχηματισμού αρχείων έχει μη έγκυρες ρυθμίσεις.',
    'The selected asset transform driver is unavailable.' => 'Το επιλεγμένο πρόγραμμα οδήγησης μετασχηματισμού αρχείων δεν είναι διαθέσιμο.',
    'The selected condition rule is invalid.' => 'Ο επιλεγμένος κανόνας συνθήκης δεν είναι έγκυρος.',
    'The selected table cell type is unavailable.' => 'Ο επιλεγμένος τύπος κελιού πίνακα δεν είναι διαθέσιμος.',
