    'There aren\'t any pending project config changes to apply.' => 'Δεν υπάρχουν εκκρεμείς αλλαγές ρυθμίσεων έργου για εφαρμογή.',
    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to search and read this site’s public content in plain language.' => 'Αυτό το URL είναι διακομιστής MCP για βοηθούς AI, όχι ιστοσελίδα. Προσθέστε το στον βοηθό σας για να αναζητάτε και να διαβάζετε το δημόσιο περιεχόμενο αυτού του ιστότοπου σε φυσική γλώσσα.',
    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to work with this site’s content and settings in plain language.' => 'Αυτό το URL είναι διακομιστής MCP για βοηθούς AI, όχι ιστοσελίδα. Προσθέστε το στον βοηθό σας για να εργάζεστε με το περιεχόμενο και τις ρυθμίσεις αυτού του ιστότοπου σε φυσική γλώσσα.',
    'This application will be able to:' => 'Αυτή η εφαρμογή θα μπορεί να:',
    'This asset transformer cannot be deleted because it is assigned to a volume.' => 'Αυτός ο μετασχηματιστής αρχείων δεν μπορεί να διαγραφεί επειδή έχει ανατεθεί σε τόμο.',
    'This asset transformer cannot be deleted because it is configured as the default.' => 'Αυτός ο μετασχηματιστής αρχείων δεν μπορεί να διαγραφεί επειδή έχει ρυθμιστεί ως προεπιλογή.',
    'This asset transformer’s driver is unavailable.' => 'Το πρόγραμμα οδήγησης αυτού του μετασχηματιστή αρχείων δεν είναι διαθέσιμο.',
    'This asset transformer’s driver is unavailable. Select an available driver to save it.' => 'Το πρόγραμμα οδήγησης αυτού του μετασχηματιστή αρχείων δεν είναι διαθέσιμο. Επιλέξτε ένα διαθέσιμο πρόγραμμα οδήγησης για να τον αποθηκεύσετε.',
    'This column type has no settings.' => 'Αυτός ο τύπος στήλης δεν έχει ρυθμίσεις.',
    'This date is for planning only. Scheduling is a separate action.' => 'Αυτή η ημερομηνία είναι μόνο για σχεδιασμό. Ο προγραμματισμός είναι ξεχωριστή ενέργεια.',
    'This date is for planning only. The release will not publish until it is explicitly scheduled.' => 'Αυτή η ημερομηνία είναι μόνο για σχεδιασμό. Η κυκλοφορία δεν θα δημοσιευτεί μέχρι να προγραμματιστεί ρητά.',
    'This disk has been reserved for temporary asset uploads. Please choose a different one for your volume.' => 'Αυτός ο δίσκος έχει δεσμευτεί για προσωρινές μεταφορτώσεις αρχείων. Επιλέξτε διαφορετικό δίσκο για τον τόμο σας.',
    'This disk reference is invalid.' => 'Αυτή η αναφορά δίσκου δεν είναι έγκυρη.',
    'This draft already belongs to an active release.' => 'Αυτό το πρόχειρο ανήκει ήδη σε ενεργή κυκλοφορία.',
    'This draft belongs to the scheduled release “{name}”. Saved changes will be included when the release publishes.' => 'Αυτό το πρόχειρο ανήκει στην προγραμματισμένη κυκλοφορία «{name}». Οι αποθηκευμένες αλλαγές θα συμπεριληφθούν όταν δημοσιευτεί η κυκλοφορία.',
    'This draft belongs to “{name}”. Saved changes will be included when the release publishes.' => 'Αυτό το πρόχειρο ανήκει στο «{name}». Οι αποθηκευμένες αλλαγές θα συμπεριληφθούν όταν δημοσιευτεί η κυκλοφορία.',
    'This draft is approved and ready to be published.' => 'Αυτό το πρόχειρο έχει εγκριθεί και είναι έτοιμο για δημοσίευση.',
    'This draft is blocking the scheduled release “{name}”.' => 'Αυτό το πρόχειρο εμποδίζει την προγραμματισμένη κυκλοφορία «{name}».',
    'This draft is blocking “{name}”.' => 'Αυτό το πρόχειρο εμποδίζει το «{name}».',
    'This draft is now blocking “{name}”.' => 'Αυτό το πρόχειρο εμποδίζει πλέον το «{name}».',
    'This draft is scheduled to publish with “{name}”. If edits leave it unready, the release will fail to publish.' => 'Αυτό το πρόχειρο είναι προγραμματισμένο να δημοσιευτεί με το «{name}». Αν οι αλλαγές το αφήσουν μη έτοιμο, η δημοσίευση της κυκλοφορίας θα αποτύχει.',
    'This draft is waiting on your approval.' => 'Αυτό το πρόχειρο περιμένει την έγκρισή σας.',
    'This draft links to unpublished content that is not part of the release.' => 'Αυτό το πρόχειρο συνδέεται με μη δημοσιευμένο περιεχόμενο που δεν αποτελεί μέρος της κυκλοφορίας.',
    'This draft must be approved before it can be applied.' => 'Αυτό το πρόχειρο πρέπει να εγκριθεί πριν μπορέσει να εφαρμοστεί.',
    'This draft was withdrawn from review.' => 'Αυτό το πρόχειρο αποσύρθηκε από την αξιολόγηση.',
    'This draft was withdrawn from review. Resubmit it when your edits are ready.' => 'Αυτό το πρόχειρο αποσύρθηκε από την αξιολόγηση. Υποβάλετέ το ξανά όταν οι αλλαγές σας είναι έτοιμες.',
    'This draft’s release is being published.' => 'Η κυκλοφορία αυτού του προχείρου δημοσιεύεται.',
    'This endpoint is in the control panel, so only users with control panel access can use it.' => 'Αυτό το endpoint βρίσκεται στον πίνακα ελέγχου, οπότε μόνο χρήστες με πρόσβαση στον πίνακα ελέγχου μπορούν να το χρησιμοποιήσουν.',
    'This entry will be expired in at least one site at the release time.' => 'Αυτή η καταχώρηση θα έχει λήξει σε τουλάχιστον έναν ιστότοπο κατά την ώρα της κυκλοφορίας.',
