    'The minimum number of rows the field is allowed to have.' => 'Ο ελάχιστος αριθμός γραμμών που επιτρέπεται να έχει το πεδίο.',
    'The minimum number of {type} that may be selected.' => 'Ο ελάχιστος αριθμός {type} που μπορούν να επιλεγούν.',
    'The minimum number of {type} the field is allowed to have.' => 'Ο ελάχιστος αριθμός {type} που επιτρέπεται να έχει το πεδίο.',
    'The number of minutes that timepicker options should be incremented by. (Authors can enter a specific time manually.)' => 'Ο αριθμός λεπτών κατά τον οποίο πρέπει να αυξάνονται οι επιλογές επιλογέα ώρας. (Οι συντάκτες μπορούν να εισάγουν συγκεκριμένη ώρα χειροκίνητα.)',
    'The number of seconds that the Retry-After HTTP header should be set to for maintenance mode responses.' => 'Ο αριθμός δευτερολέπτων που θα ορίζεται στην κεφαλίδα HTTP Retry-After για τις αποκρίσεις σε λειτουργία συντήρησης.',
    'The path can contain variables like `{slug}` or `{author.username}`.' => 'Η διαδρομή μπορεί να περιέχει μεταβλητές όπως `{slug}` ή `{author.username}`.',
    'The path to a template file within your `templates/` folder.' => 'Η διαδρομή προς ένα αρχείο προτύπου στον φάκελο `templates/` σας.',
    'The plugin was removed successfully.' => 'Η επέκταση αφαιρέθηκε επιτυχώς.',
    'The posted condition config is invalid.' => 'Η υποβληθείσα διαμόρφωση συνθήκης δεν είναι έγκυρη.',
    'The primary site cannot be disabled.' => 'Ο κύριος ιστότοπος δεν μπορεί να απενεργοποιηθεί.',
    'The primary site will be loaded by default on the front end.' => 'Ο κύριος ιστότοπος θα φορτώνεται από προεπιλογή στο frontend.',
    'The request could not be understood by the server due to malformed syntax.' => 'Το αίτημα δεν ήταν δυνατό να γίνει κατανοητό από τον διακομιστή λόγω εσφαλμένης σύνταξης.',
    'The requested URL was not found on this server.' => 'Η ζητούμενη URL δεν βρέθηκε σε αυτόν τον διακομιστή.',
    'The selected condition class is invalid.' => 'Η επιλεγμένη κλάση συνθήκης δεν είναι έγκυρη.',
    'The selected {relatedType} {count, plural, =1{contains} other{contain}} validation errors, preventing this {type} from being saved. Edit the {relatedType} to fix them.' => 'The selected {relatedType} {count, plural, =1{contains} other{contain}} validation errors, preventing this {type} from being saved. Edit the {relatedType} to fix them.',
    'The selected {type} could not be found.' => 'Δεν ήταν δυνατή η εύρεση του επιλεγμένου {type}.',
    'The server doesn’t meet Craft’s new requirements:' => 'Ο διακομιστής δεν πληροί τις νέες απαιτήσεις του Craft:',
    'The subpath cannot overlap with any other volumes sharing the same filesystem.' => 'Η υποδιαδρομή δεν μπορεί να επικαλύπτεται με άλλους τόμους που μοιράζονται το ίδιο σύστημα αρχείων.',
    'The template Craft CMS will use for HTML emails' => 'Το πρότυπο που θα χρησιμοποιεί το Craft CMS για email HTML',
    'The template Craft CMS will use for HTML emails. Leave blank to use the default template.' => 'Το πρότυπο που θα χρησιμοποιεί το Craft CMS για τα email HTML. Αφήστε το κενό για να χρησιμοποιηθεί το προεπιλεγμένο πρότυπο.',
    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => 'Το πρότυπο λαμβάνει τις μεταβλητές `element` και `static`. Η έξοδός του καθαρίζεται και εμφανίζεται ως μη διαδραστικό περιεχόμενο· τα στοιχεία ελέγχου φορμών, τα scripts και τα καταχωρημένα assets δεν υποστηρίζονται.',
    'The template will be rendered with an `element` variable.' => 'Το πρότυπο θα αποδοθεί με τη μεταβλητή `element`.',
    'The text label for the entry creation button.' => 'Η ετικέτα κειμένου για το κουμπί δημιουργίας καταχώρησης.',
    'The text label for {type} selection buttons.' => 'Η ετικέτα κειμένου για τα κουμπιά επιλογής {type}.',
    'The text that will be shown if the field doesn’t have a value.' => 'Το κείμενο που θα εμφανίζεται εάν το πεδίο δεν έχει τιμή.',
    'The total number of {type} to display per page within the element index.' => 'Ο συνολικός αριθμός {type} που θα εμφανίζονται ανά σελίδα στο ευρετήριο στοιχείων.',
    'The update can’t be installed :( {message}' => 'Η ενημέρωση δεν μπορεί να εγκατασταθεί :( {message}',
    'The update was reverted successfully.' => 'Η ενημέρωση αναστράφηκε επιτυχώς.',
    'The uploaded file exceeds the maximum allowed size.' => 'Το ανεβασμένο αρχείο υπερβαίνει το μέγιστο επιτρεπόμενο μέγεθος.',
    'The user photo provided is not an image.' => 'Η φωτογραφία χρήστη που παρέχεται δεν είναι εικόνα.',
    'The user photo provided is not valid.' => 'Η φωτογραφία χρήστη που δόθηκε δεν είναι έγκυρη.',
    'The values are matched inclusively.' => 'Οι τιμές αντιστοιχίζονται συμπεριληπτικά.',
    'The volume where pasted or dropped files should be uploaded.' => 'Ο τόμος όπου θα μεταφορτώνονται τα αρχεία που επικολλώνται ή αποθέτονται.',
    'The volumes that should be available when selecting assets.' => 'Οι τόμοι που θα είναι διαθέσιμοι κατά την επιλογή αρχείων.',
    'The {attribute} field must be a string or array.' => 'Το πεδίο {attribute} πρέπει να είναι συμβολοσειρά ή πίνακας.',
    'The {attribute} field must contain a `class` value.' => 'Το πεδίο {attribute} πρέπει να περιέχει τιμή `class`.',
    'The {field} field’s {setting} setting has an invalid subpath (“{subpath}”).' => 'Η ρύθμιση {setting} του πεδίου {field} έχει μη έγκυρη υποδιαδρομή («{subpath}»).',
    'The {field} field’s {setting} setting is set to an invalid volume.' => 'Η ρύθμιση {setting} του πεδίου {field} έχει οριστεί σε μη έγκυρο τόμο.',
    'The {name} license is attached to a different Craft CMS license. You can <a class="go" href="{detachUrl}">detach it in Craft Console</a> or <a class="go" href="{buyUrl}">buy a new license</a>.' => 'Η άδεια χρήσης {name} συνδέεται με διαφορετική άδεια Craft CMS. Μπορείτε να <a class="go" href="{detachUrl}">την αποσυνδέσετε στο Craft Console</a> ή να <a class="go" href="{buyUrl}">αγοράσετε νέα άδεια</a>.',
    'The {name} license is invalid.' => 'Η άδεια χρήσης {name} δεν είναι έγκυρη.',
    'The {numEntries, plural, =1{entry} other {entries}} will be updated once the {numUsers, plural, =1{user is} other{users are}} deleted.' => 'Η/οι {numEntries, plural, one {}=1{καταχώρηση} other {καταχωρήσεις}} θα ενημερωθεί(-ούν) μόλις διαγραφεί {numUsers, plural, one {}=1{χρήστης} other{χρήστες}}.',
    'The {numRelations, plural, =1{relation} other {relations}} will be removed once the {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} deleted.' => 'Ο/οι {numRelations, plural, one {}=1{συσχετισμός} other {συσχετισμοί}} θα αφαιρεθεί μόλις {numTargets, plural, one {}=1{{targetTypeSingular} διαγραφεί} other{{targetTypePlural} διαγραφούν}}.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => '{numTargets, plural, =1{Το {targetTypeSingular} αναφέρεται} other{Τα {targetTypePlural} αναφέρονται}} από πεδία σε {numSources, number} {numSources, plural, =1{άλλο στοιχείο} other{άλλα στοιχεία}}.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} related by {numRelations, number} other {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}}.' => '{numTargets, plural, one {}=1{{targetTypeSingular} Συσχετίζεται} other{{targetTypePlural} Συσχετίζονται}} από {numRelations, number} ακόμα {numRelations, plural, one {}=1{{sourceTypeSingular}} other{{sourceTypePlural}}}.',
    'The {type} is invalid.' => 'Το {type} δεν είναι έγκυρο.',
