    'This can be set to an environment variable with a value of a [supported time zone]({url}).' => 'Αυτό μπορεί να οριστεί σε μεταβλητή περιβάλλοντος με τιμή [υποστηριζόμενης ζώνης ώρας]({url}).',
    'This can be set to an environment variable, or a Twig template that outputs an ID.' => 'Αυτό μπορεί να οριστεί σε μεταβλητή περιβάλλοντος ή πρότυπο Twig που εξάγει αναγνωριστικό.',
    'This can be set to an environment variable, or a Twig template that outputs comma-separated IDs.' => 'Αυτό μπορεί να οριστεί σε μεταβλητή περιβάλλοντος ή πρότυπο Twig που εξάγει αναγνωριστικά διαχωρισμένα με κόμμα.',
