    'This element is conditional' => 'Αυτό το στοιχείο είναι υπό συνθήκη',
    'This entry type’s {attributes} {totalAttributes, plural, =1{has} other{have}} been overridden.' => 'Τα {attributes} αυτού του τύπου καταχώρησης {totalAttributes, plural, =1{έχει} other{έχουν}} παρακαμφθεί.',
