    'This filesystem has been reserved for temporary asset uploads. Please choose a different one for your volume.' => 'Αυτό το σύστημα αρχείων έχει δεσμευτεί για προσωρινές μεταφορτώσεις αρχείων. Επιλέξτε ένα διαφορετικό για τον τόμο σας.',
