    'What’s New' => 'Τι νέο υπάρχει',
    'When enabled, site requests will return a service unavailable response and queued jobs will pause.' => 'Όταν είναι ενεργοποιημένο, τα αιτήματα στον ιστότοπο θα επιστρέφουν απόκριση μη διαθέσιμης υπηρεσίας και οι εργασίες στην ουρά θα τίθενται σε παύση.',
    'When someone replaces a file, the record of who uploaded the file will be updated as well.' => 'Όταν κάποιος αντικαθιστά ένα αρχείο, θα ενημερώνεται και η καταγραφή του ατόμου που ανέβασε το αρχείο.',
    'Where assets should be stored (relative to **Asset Location**) when they are uploaded directly to the field.' => 'Πού θα αποθηκεύονται τα αρχεία (σχετικά με την **Τοποθεσία Αρχείων**) όταν ανεβαίνουν απευθείας στο πεδίο.',
    'Where assets should be stored on the filesystem.' => 'Πού θα αποθηκεύονται τα αρχεία στο σύστημα αρχείων.',
    'Where assets should be stored when they are uploaded directly to the field.' => 'Πού θα αποθηκεύονται τα αρχεία όταν ανεβαίνουν απευθείας στο πεδίο.',
    'Where do you want to store user photos? Note that the subfolder path can contain variables like {username}.' => 'Πού θέλετε να αποθηκεύονται οι φωτογραφίες χρηστών; Σημειώστε ότι η διαδρομή του υποφακέλου μπορεί να περιέχει μεταβλητές όπως {username}.',
    'Where new {type} should be placed by default in the field.' => 'Πού θα τοποθετούνται από προεπιλογή τα νέα {type} στο πεδίο.',
    'Where new {type} should be placed by default in the structure.' => 'Πού θα τοποθετούνται από προεπιλογή τα νέα {type} στη δομή.',
    'Where transforms should be stored on the filesystem.' => 'Πού θα αποθηκεύονται οι μετατροπές στο σύστημα αρχείων.',
    'Whether HTML should be encoded before rendering the Markdown.' => 'Αν θα κωδικοποιείται η HTML πριν από την απόδοση του Markdown.',
    'Whether authors should be able to choose which time zone the time is in.' => 'Αν οι συντάκτες θα μπορούν να επιλέγουν σε ποια ζώνη ώρας ανήκει η ώρα.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'Αν οι συντάκτες θα μπορούν να ανεβάζουν αρχεία απευθείας στο πεδίο, αντί να απαιτείται η επιλογή/ανέβασμα αρχείων μέσω του παραθύρου επιλογής.',
    'Whether buttons should only show their icons, hiding their text labels.' => 'Αν τα κουμπιά θα εμφανίζουν μόνο τα εικονίδιά τους, αποκρύπτοντας τις ετικέτες κειμένου τους.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.',
    'Whether custom fields should be validated during public registration.' => 'Αν τα προσαρμοσμένα πεδία θα επικυρώνονται κατά τη δημόσια εγγραφή.',
    'Whether the editor should show character, word, and line counts.' => 'Αν ο επεξεργαστής θα εμφανίζει πλήθος χαρακτήρων, λέξεων και γραμμών.',
    'Whether the editor toolbar should be visible.' => 'Αν θα είναι ορατή η γραμμή εργαλείων του επεξεργαστή.',
    'Whether the element index should allow viewing nested {type} in a table.' => 'Αν το ευρετήριο στοιχείων θα επιτρέπει την προβολή ένθετων {type} σε πίνακα.',
    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => 'Αν το πεδίο θα αποδίδει μόνο ενσωματωμένο Markdown, χωρίς να το περικλείει σε παραγράφους.',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => 'Αν θα εμφανίζεται ο αριθμός των στοιχείων αυτής της πηγής δίπλα της στην πλοήγηση.',
    'Whether the site menu should be shown for {type} selection modals.' => 'Αν το μενού ιστότοπου θα εμφανίζεται σε παράθυρα επιλογής {type}.',
    'Whether the structure of the related {type} should be maintained.' => 'Αν η δομή του σχετικού {type} θα διατηρείται.',
    'Whether the table rows should be restricted to those defined by the “Default Values” setting.' => 'Αν οι γραμμές του πίνακα θα περιορίζονται σε αυτές που ορίζονται από τη ρύθμιση «Προεπιλεγμένες τιμές».',
    'Whether this can be dismissed by a user and not shown again.' => 'Αν αυτό μπορεί να απορριφθεί από ένα χρήστη και να μη εμφανιστεί ξανά.',
    'Whether to show entries that the user doesn’t have permission to view, per the “View other users’ entries” permission.' => 'Αν θα εμφανίζονται καταχωρήσεις για τις οποίες ο χρήστης δεν έχει δικαίωμα προβολής, σύμφωνα με το δικαίωμα «Προβολή καταχωρήσεων άλλων χρηστών».',
    'Whether to show files that the user doesn’t have permission to view, per the “View files uploaded by other users” permission.' => 'Αν θα εμφανίζονται αρχεία για τα οποία ο χρήστης δεν έχει δικαίωμα προβολής, σύμφωνα με το δικαίωμα «Προβολή αρχείων που έχουν ανεβαστεί από άλλους χρήστες».',
    'Whether to show sections that the user doesn’t have permission to view.' => 'Αν θα εμφανίζονται ενότητες για τις οποίες ο χρήστης δεν έχει δικαίωμα προβολής.',
    'Whether to show volumes that the user doesn’t have permission to view.' => 'Αν θα εμφανίζονται τόμοι για τους οποίους ο χρήστης δεν έχει δικαίωμα προβολής.',
    'Whether validation errors on the related {type} should prevent the source element from being saved.' => 'Αν τα σφάλματα επικύρωσης στο σχετικό {type} θα εμποδίζουν την αποθήκευση του στοιχείου πηγής.',
    'Whether {type} elements should be allowed to relate to themselves.' => 'Αν τα στοιχεία {type} θα επιτρέπεται να σχετίζονται με τον εαυτό τους.',
    'Which group should this site belong to?' => 'Σε ποια ομάδα θα ανήκει αυτός ο ιστότοπος;',
